{
  "qa": [
    {
      "question": "当前公司上半年的市场营销情况如何？",
      "answer": "上半年公司主要通过篮球架等运动项目打开市场，其中篮球架因学校和公园等场所需求较大而成为销售主力，羽毛球拍等其他运动器材的市场仍在逐步开拓中。"
    },
    {
      "question": "公司目前是否有风险投资合作项目？",
      "answer": "公司目前未开展风险投资相关项目，但已与篮球生产公司及浴室配套生产公司合作，资金方面较为充裕。"
    },
    {
      "question": "公司计划在下半年引入筋膜枪服务的具体内容是什么？",
      "answer": "公司计划与国外筋膜枪供应商合作，针对打篮球后肌肉紧绷问题提供按摩服务，需招募精通按摩原理及力度控制的专业人员。"
    }
  ]
}
